def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.25)
        if hp <= 2 or no_water_days >= 2:
            safe_bid = min(budget, DAILY_SALARY * 0.6)
        return float(max(0.0, safe_bid))

    prev_bids = []
    prev_high = 0.0
    prev_avg = 0.0
    desperate_count = 0
    rich_count = 0

    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 8:
            rich_count += 1
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = float(prev.get('bid', 0.0))
            prev_bids.append(b)
            if b > prev_high:
                prev_high = b

    if prev_bids:
        prev_avg = sum(prev_bids) / len(prev_bids)

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    if hp <= 1 or no_water_days >= 2:
        base = max(92.0, prev_high + 2.0)
    elif hp <= 3 or no_water_days == 1:
        base = max(74.0, prev_avg + 2.0, prev_high * 0.9)
    else:
        if tight_supply:
            base = max(68.0, prev_avg + 1.5)
        elif medium_supply:
            base = max(52.0, prev_avg * 0.78)
        else:
            base = max(28.0, prev_avg * 0.55)

    if prev_high >= 120:
        if hp >= 4 and no_water_days == 0:
            base = min(base, 38.0)
        else:
            base = max(base, 88.0)
    elif prev_high >= 95:
        if hp >= 5 and no_water_days == 0 and not tight_supply:
            base = min(base, 44.0)
        else:
            base = max(base, 72.0)

    if desperate_count >= 2 and medium_supply:
        base += 8.0
    elif desperate_count >= 1 and tight_supply:
        base += 5.0

    if rich_count >= 2 and hp >= 4 and no_water_days == 0 and not tight_supply:
        base -= 6.0

    if day >= 8:
        if hp <= 3:
            base += 10.0
        else:
            base += 4.0

    if budget < DAILY_SALARY * 2:
        base = min(base, budget * 0.72)
    elif budget < DAILY_SALARY * 4:
        base = min(base, budget * 0.58)

    min_guard = 0.0
    if hp <= 2 or no_water_days >= 2:
        min_guard = 60.0
    elif hp <= 3 or no_water_days == 1:
        min_guard = 42.0
    elif tight_supply:
        min_guard = 34.0
    else:
        min_guard = 20.0

    bid = max(base, min_guard)
    bid = min(budget, bid)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 90
    WATER_REQ = 9
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Determine yesterday's max bid among alive opponents
    yesterday_max_bid = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_max_bid = max(yesterday_max_bid, prev['bid'])

    # Scarcity factor: higher when supply per capita is low
    scarcity_factor = max(0.5, 1 - (supply / (len(alive_opponents) + 1) / WATER_REQ))

    # Dehydration urgency
    if no_water_days >= 1:
        target_bid = min(my_budget, DAILY_SALARY * 0.9)
        if my_hp <= 2:
            target_bid = min(my_budget, DAILY_SALARY * 0.95)
    else:
        if yesterday_max_bid > 0:
            if yesterday_max_bid >= DAILY_SALARY * 0.8:
                if my_budget > DAILY_SALARY:
                    target_bid = min(my_budget, max(DAILY_SALARY * 0.5, yesterday_max_bid * 0.95))
                else:
                    target_bid = min(my_budget, DAILY_SALARY * 0.3)
            else:
                target_bid = min(my_budget, yesterday_max_bid + 2)
        else:
            target_bid = min(my_budget, DAILY_SALARY * (0.4 + scarcity_factor * 0.3))

    final_bid = max(0, min(my_budget, target_bid))
    if no_water_days >= 2 and my_hp <= 5:
        final_bid = max(final_bid, min(my_budget, DAILY_SALARY * 0.85))

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    yesterday_bids = []
    yesterday_hp_after = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid', 0.0)))
                yesterday_hp_after.append(float(prev.get('hp_after', 0.0)))
            except Exception:
                pass

    # If no info, default conservative
    if not yesterday_bids:
        base = DAILY_SALARY * 0.55
        return max(0.0, min(float(my_status['budget']), base))

    highest_prev_bid = max(yesterday_bids)
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Pressure estimate: if any opponent bid very high yesterday, they likely continue
    high_pressure = highest_prev_bid >= (DAILY_SALARY * 0.75)  # ~112.5
    med_pressure = highest_prev_bid >= (DAILY_SALARY * 0.45)   # ~67.5

    # Supply factor: when supply is higher, we can afford to bid more competitively
    # Normalize supply into [0,1]
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_norm = 0.5
    else:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    # Determine target bid
    # Goal: slightly above the likely top competitor, but cap to avoid bankruptcy.
    # Use second-highest to reduce overpaying when only one opponent was extreme.
    if high_pressure:
        # Compete strongly
        target = max(second_prev_bid + 5.0, DAILY_SALARY * (0.55 + 0.25 * supply_norm))
    elif med_pressure:
        # Moderate competition
        target = max(second_prev_bid + 2.0, DAILY_SALARY * (0.45 + 0.20 * supply_norm))
    else:
        # Low pressure: conserve
        target = DAILY_SALARY * (0.35 + 0.15 * supply_norm)

    # Urgency adjustments based on my HP / no-water streak
    if my_hp <= 2.0 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif my_hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.65)

    # Safety cap: don't bid more than what we can sustain for remaining days (approx)
    # We don't know remaining days precisely; use budget fraction heuristic.
    budget_cap = my_budget
    if my_budget <= 0:
        return 0.0

    # If budget is low, scale down target
    if my_budget < DAILY_SALARY * 0.6:
        target = min(target, my_budget * 0.85)

    # Final bid within [0, budget]
    bid = max(0.0, min(budget_cap, target))

    # Small anti-tie jitter using day parity (deterministic)
    if int(day) % 2 == 0:
        bid = bid + 0.5
    else:
        bid = bid - 0.5

    if bid < 0.0:
        bid = 0.0
    if bid > my_budget:
        bid = my_budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    available_water_slots = int(day_context['supply'] // WATER_REQ)
    num_active_players = 1 + len(alive_opponents)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.7

    if num_active_players > available_water_slots:
        # High competition: need to bid more aggressively
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 1.0:
                base_bid = max(base_bid, highest_prev_bid * 1.05)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
    else:
        # Lower competition: can be more conservative or react to high bids
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid >= DAILY_SALARY * 0.9:
                base_bid = max(base_bid, highest_prev_bid * 0.95)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)

    if my_status['hp'] <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 1.2)
    elif my_status['hp'] <= 4 and day_context['day'] > EPISODE_DAYS / 2:
        base_bid = max(base_bid, DAILY_SALARY * 1.1)

    final_bid = min(my_status['budget'], base_bid)

    if final_bid == 0 and my_status['budget'] > 0:
        final_bid = 1.0

    return final_bid

